  "{0} has lost its last port, but loyal servants have not abandoned the flag. This expedition can keep our cause alive overseas until fortune turns.": "{0} 失去了最後的港口，但忠誠的僕人並沒有放棄旗幟。這次遠徵可以讓我們的事業在海外繼續存在，直到命運轉變。",
