  "DEMO": "示範版",
  "Denali rises from low country with scarcely any warning, an immense wall of snow above rivers and dark forest. Clouds crossed its middle while the summit remained in another weather.": "麥金利峰從低地升起，幾乎沒有任何預兆，河流和黑暗的森林上方是一堵巨大的雪牆。雲層穿過中部，而山頂仍處於另一種天氣。",
