  "Great Explorer": "偉大的探險家",
  "Great figures scored into the desert. Who were they meant to see?": "偉大的人物進入了沙漠。他們要見誰？",
  "Great walls curve across the plateau, built from fitted stone without a trace of mortar. Narrow passages lead between towers and enclosures above the grasslands.": "長城蜿蜒地橫跨高原，由合適的石頭建造而成，沒有一絲砂漿。狹窄的通道通往草原上方的塔樓和圍牆之間。",
  "Great Zimbabwe": "大辛巴威",
  "Guanabara is already defended. The expedition requires": "瓜納巴拉已經被防守。這次探險需要",
  "Gujarat": "古吉拉特邦",
  "Gujarat Sultanate": "古吉拉特邦蘇丹國",
  "Gujarati": "古吉拉特語",
  "GUN": "槍",
  "Gun Captain": "槍隊長",
  "Guns": "槍",
  "guns, gates, cranes, and ship repairs": "槍支、大門、起重機和船舶修理",
  "H{0} A{1} P{2} C{3}": "H{0} A{1} P{2} C{3}",
  "Habsburg": "哈布斯堡王朝",
  "Habsburg Monarchy": "哈布斯堡王朝",
  "Hail: {0}": "呼叫：{0}",
  "Hajj keepsake: Zamzam Flask": "朝覲紀念品：滲滲泉瓶",
  "Half the World": "半個世界",
  "Hamazor bem, captain. It is not often I greet another of our faith across this counter.": "哈馬佐爾，隊長。我很少在櫃檯對面迎接我們信仰的另一個人。",
  "Hand over the captive": "交出俘虜",
  "Happy birthday, {0}. Another year older, and still one of the steadiest souls aboard.": "生日快樂，{0}。又老了一歲，但仍然是船上最穩定的靈魂之一。",
  "Harbor boats weave among galleys and merchantmen while clerks bargain over berths, cargo, and the next convoy.": "港口船隻在槳帆船和商船之間穿梭，而職員則就泊位、貨物和下一個船隊討價還價。",
  "harbor dispatch": "港口調度",
