  "Panda Aboard East of Taiwan": "台灣東部的熊貓",
  "Panda Aboard in the Indian Ocean": "印度洋上的熊貓",
  "Panda Aboard in the Seto Inland Sea": "瀨戶內海的熊貓",
  "Panda Aboard on the Homeward Voyage": "熊貓踏上歸途",
  "Panok ship (Panokseon) | 판옥선 | 板屋船": "板諾（Panokseon）| 판옥선 | 板屋船",
  "Panokseon": "板綠船",
  "Papal": "教宗",
  "Papal Admonition": "教宗的訓誡",
  "Papal Alms Mission": "教宗施捨使命",
  "Papal Commendation": "教宗嘉獎",
  "PAPAL GRAIN ALMS UNDERWAY FOR {0}": "教宗正在為 {0} 進行穀物施捨",
  "PAPAL LEGATION EXPIRED - ROME ACTS WITHOUT US": "教宗使節到期 - 羅馬在沒有我們的情況下行事",
  "PAPAL LEGATION REVOKED": "教宗使節被撤銷",
  "Papal Peace Commission": "教宗和平委員會",
  "Papal Reform Commission": "教宗改革委員會",
  "PAPAL RELIEF REACHES {0} AGAINST {1}": "教宗救濟達到 {0} 反對 {1}",
  "PAPAL RELIEF UNDERWAY FOR {0} AGAINST {1}": "教宗正在為 {0} 和 {1} 提供救濟",
