  "Remarkable. Leave the penguin in my care and I shall pay you {payment} doubloons. I have fish, ink, and several questions he may decline to answer.": "了不起。把企鵝交給我照顧，我將付給你{付款}達布隆。我有魚、墨水，還有幾個他可能會拒絕回答的問題。",
