  "SEA ICE PARTED THE HARPOON LINE": "海冰分開了魚叉線",
  "Sea Venture survivors built Deliverance and Patience from Bermuda cedar before reaching Jamestown. Their account now inspires a town at St. George's.": "Sea Venture 的倖存者在到達詹姆斯敦之前用百慕大雪鬆建造了拯救號和耐心號。他們的故事如今為聖喬治鎮的一座小鎮帶來了靈感。",
