  "Set crew, guns, and stores. Extra hands improve field work and gun loading. Smaller stores dump excess provisions without refund.": "設置人員、槍支和物資。額外的人手可以改善現場工作和槍支裝載。較小的商店傾倒多餘的食物，不予退款。",
