  "Sharifate of Mecca": "麥加謝里夫特",
  "Shasta rises by itself above the forests, a broad volcanic cone with a smaller shoulder beside it. Snowfields catch the light long after the lower country has gone dark.": "沙斯塔在森林上方獨自升起，是一個寬闊的火山錐，旁邊有一個較小的肩膀。低地地區天黑很久之後，雪原仍能看到陽光。",
  "Shawmut has good water but little ready shelter for a fleet of families. Bring": "肖穆特擁有良好的水源，但幾乎沒有為一大群家庭準備好的住所。帶",
  "Shawmut's spring solves the water crisis that plagued Charlestown. We will establish Boston on this narrow peninsula in the country of the Massachusett.": "肖姆特的泉水解決了困擾查爾斯敦的水危機。我們將在馬薩諸塞州這個狹窄的半島上建立波士頓。",
  "Shimazu": "島津",
  "Shimazu House": "島津屋",
  "Shinto-Buddhist": "神道佛教",
